You are a strict code reviewer. Two diffs (A, B) solve the SAME task. Which is higher quality (correctness, completeness, no broken cross-file refs)? Reply with exactly one token: A or B.
=== DIFF A ===
diff --git a/lib/matching/__tests__/write-path-parity.test.ts b/lib/matching/__tests__/write-path-parity.test.ts
new file mode 100644
index 00000000..b9fd13f1
--- /dev/null
+++ b/lib/matching/__tests__/write-path-parity.test.ts
@@ -0,0 +1,332 @@
+/**
+ * Write-path parity test — B.2
+ *
+ * Both compute-matches.ts (background precompute) and persist-session-matches.ts
+ * (live session persist) must write the same 21 key columns for an identical
+ * cargo×vessel match so the rendered card looks the same regardless of which
+ * path saved the row.
+ *
+ * Columns checked (excluding id, status, user_id, created_at, updated_at):
+ *   cargo_id, vessel_id, score, reason_structured,
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   vessel_name, cargo_ref,
+ *   fit_percent, fit_breakdown (keys), cargo_item_index, vessel_item_index,
+ *   breakeven_tce_usd_per_day
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, Match, MatchReadiness, MatchHardFilters, MatchSanctions, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_ID = 'parity-cargo';
+const VESSEL_ID = 'parity-vessel';
+const SESSION_A = 'parity-session-a';
+const SESSION_B = 'parity-session-b';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const CARGO: ParsedCargo = {
+  emailId: CARGO_ID,
+  itemIndex: 1,
+  originPort: { value: 'Hamburg', confidence: 'confirmed' },
+  destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+  cargoType: 'grain',
+  laycan: '1-15 Aug 2025',
+  freightRateUsd: null,
+  cargoDescription: { value: 'Yellow corn', confidence: 'confirmed' },
+  weightMt: { value: 48000, confidence: 'confirmed' },
+  weightMtMin: null,
+  weightMtMax: null,
+  volumeCbm: null,
+  dimensions: null,
+  containerType: null,
+  quantity: null,
+  incoterms: null,
+  preferredDates: null,
+  loadingRate: null,
+  dischargeRate: null,
+  commissionPercent: null,
+  commissionTerms: null,
+  specialRequirements: null,
+  stowageFactor: null,
+  missingInfo: [],
+  originCountry: null,
+  destinationCountry: null,
+};
+
+const VESSEL: ParsedVessel = {
+  emailId: VESSEL_ID,
+  itemIndex: 2,
+  dwtSummer: { value: 56000, confidence: 'confirmed' },
+  vesselName: { value: 'MV PARITY', confidence: 'confirmed' },
+  imo: null,
+  flag: 'Panama',
+  built: 2012,
+  classSociety: 'BV',
+  pandi: null,
+  dwcc: null,
+  draftMax: { value: 12.5, confidence: 'confirmed' },
+  loa: null,
+  beam: null,
+  grt: null,
+  nrt: null,
+  holdsCount: null,
+  hatchesCount: null,
+  grainCapacity: 71000,
+  grainCapacityUnit: 'cbm',
+  baleCapacity: null,
+  holdDimensions: null,
+  hatchDimensions: null,
+  tankTopStrength: null,
+  geared: false,
+  craneCapacity: null,
+  hatchType: null,
+  vesselType: 'bulk',
+  openPosition: { value: 'Hamburg', confidence: 'confirmed' },
+  openDate: { value: '2025-07-25', confidence: 'confirmed' },
+  direction: null,
+  restrictions: [],
+  lastCargoes: null,
+  speedLaden: '13.5',
+  speedBallast: null,
+  consumption: '28',
+  deckCapacity: null,
+  specialFeatures: [],
+};
+
+const READINESS: MatchReadiness = {
+  openDate: '2025-07-25',
+  laycanStart: '2025-08-01',
+  laycanEnd: '2025-08-15',
+  distanceNm: 15500,
+  distanceExact: true,
+  speedKn: 13.5,
+  sailingDays: 28,
+  arrivalDate: '2025-08-22',
+  gapDays: 7,
+  verdict: 'idle',
+  explanation: 'Open 7 days before laycan',
+};
+
+const HARD_FILTERS: MatchHardFilters = {
+  draft: { pass: true },
+  crane: { pass: true },
+  volume: { pass: true },
+  cargoVessel: { pass: true },
+  destDraft: { pass: true },
+  destCrane: { pass: true },
+  cargoWeight: { pass: true },
+};
+
+const SANCTIONS: MatchSanctions = { risk: 'NONE', blocking: false };
+
+const FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Utilisation', weight: 19, score: 17, rationale: 'Good utilisation' },
+    { factor: 'timing', label: 'Timing', weight: 15, score: 12, rationale: 'Idle 7 days' },
+    { factor: 'ballast', label: 'Ballast', weight: 15, score: 13, rationale: 'Moderate ballast' },
+    { factor: 'classFit', label: 'Class fit', weight: 9, score: 7, rationale: 'OK class' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 6, score: 6, rationale: 'Grain → bulk' },
+    { factor: 'cranes', label: 'Cranes', weight: 6, score: 6, rationale: 'No crane needed' },
+    { factor: 'volume', label: 'Volume', weight: 3, score: 3, rationale: 'Volume fits' },
+    { factor: 'draft', label: 'Draft', weight: 2, score: 2, rationale: 'Draft OK' },
+    { factor: 'vetting', label: 'Vetting', weight: 7, score: 5, rationale: 'Moderate age' },
+    { factor: 'economics', label: 'Economics', weight: 18, score: 12, rationale: 'Breakeven positive' },
+  ],
+  totalWeight: 100,
+  fitPercent: 83,
+  partCargo: false,
+  vesselClass: 'supramax',
+  sanctionsPenalty: 0,
+  chartererPenalty: 0,
+  appliedCap: null,
+  inputs: { distanceNm: 15500, gapDays: 7, verdict: 'idle', utilisation: 0.857, vesselDwt: 56000, cargoWtMax: 48000 },
+};
+
+const BASE_MATCH: Match = {
+  cargoEmailId: CARGO_ID,
+  cargoItemIndex: 1,
+  vesselEmailId: VESSEL_ID,
+  vesselItemIndex: 2,
+  score: 83,
+  matchLevel: 'good',
+  matchReasons: ['Strong DWT utilisation, good timing'],
+  issues: [],
+  readiness: READINESS,
+  hardFilters: HARD_FILTERS,
+  sanctions: SANCTIONS,
+  fitPercent: 83,
+  fitBreakdown: FIT_BREAKDOWN,
+  scoreBreakdown: undefined,
+};
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity — compute-matches vs persist-session-matches', () => {
+  it('both paths write identical values for the 21 key columns', async () => {
+    const db = freshDb();
+
+    (analyzePairs as jest.Mock).mockResolvedValue({
+      matches: [BASE_MATCH],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+
+    // Path A: background precompute
+    await computeAndPersistMatches([CARGO], [VESSEL], SESSION_A, db);
+
+    // Path B: live session persist (uses same match data)
+    // Build the worksheet that persist-session-matches.ts expects on m.worksheet.
+    // In the live path, pair-analyzer sets it; here we stub it inline.
+    const matchWithWorksheet: Match = {
+      ...BASE_MATCH,
+      worksheet: {
+        readiness: { ...READINESS, openPosition: 'Hamburg' },
+        vessel: {
+          draftMax: 12.5,
+          grainCapacity: 71000,
+          grainCapacityUnit: 'cbm',
+          geared: false,
+          vesselType: 'bulk',
+          flag: 'Panama',
+          built: 2012,
+          pandi: null,
+          classSociety: 'BV',
+          lastCargoes: null,
+          dwtSummer: 56000,
+          dwcc: null,
+        },
+        cargo: {
+          weightMt: 48000,
+          weightMtEffective: 48000,
+          cargoType: 'grain',
+          loadPort: 'Hamburg',
+          dischargePort: 'Singapore',
+        },
+        hardFilters: HARD_FILTERS,
+        sanctions: SANCTIONS,
+      },
+    };
+    persistSessionMatches(db, SESSION_B, [matchWithWorksheet], [CARGO], [VESSEL]);
+
+    const [rowA] = listMatches(db, { user_id: SESSION_A, sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(db, { user_id: SESSION_B, sortBy: 'score', sortDir: 'desc' });
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    // cargo_id / vessel_id
+    expect(rowB.cargo_id).toBe(rowA.cargo_id);
+    expect(rowB.vessel_id).toBe(rowA.vessel_id);
+
+    // item indices
+    expect(rowA.cargo_item_index).toBe(1);
+    expect(rowA.vessel_item_index).toBe(2);
+    expect(rowB.cargo_item_index).toBe(rowA.cargo_item_index);
+    expect(rowB.vessel_item_index).toBe(rowA.vessel_item_index);
+
+    // fit_percent — both non-null; path B patches the economics component with live
+    // TCE from computeStoredMatchEconomics so the exact value may differ from path A
+    // (which stores m.fitPercent directly from analyzePairs). Both must be > 0.
+    expect(rowA.fit_percent).toBe(83);   // path A stores m.fitPercent verbatim
+    expect(rowB.fit_percent).not.toBeNull();
+    expect(rowB.fit_percent).toBeGreaterThan(0);
+
+    // fit_breakdown — both present with same component count and factor names
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
+    const fbA = JSON.parse(rowA.fit_breakdown!);
+    const fbB = JSON.parse(rowB.fit_breakdown!);
+    expect(fbA.components.length).toBe(10);
+    expect(fbB.components.length).toBe(fbA.components.length);
+    expect(fbA.components.map((c: { factor: string }) => c.factor)).toEqual(
+      fbB.components.map((c: { factor: string }) => c.factor),
+    );
+
+    // breakeven_tce_usd_per_day (both derived from vessel DWT=56000 → 5500)
+    expect(rowA.breakeven_tce_usd_per_day).toBe(5500);
+    expect(rowB.breakeven_tce_usd_per_day).toBe(rowA.breakeven_tce_usd_per_day);
+
+    // cargo_type
+    expect(rowA.cargo_type).toBe('grain');
+    expect(rowB.cargo_type).toBe(rowA.cargo_type);
+
+    // load_port / discharge_port
+    expect(rowA.load_port).toBe('Hamburg');
+    expect(rowA.discharge_port).toBe('Singapore');
+    expect(rowB.load_port).toBe(rowA.load_port);
+    expect(rowB.discharge_port).toBe(rowA.discharge_port);
+
+    // laycan window
+    expect(rowA.laycan_start).not.toBeNull();
+    expect(rowA.laycan_end).not.toBeNull();
+    expect(rowB.laycan_start).toBe(rowA.laycan_start);
+    expect(rowB.laycan_end).toBe(rowA.laycan_end);
+
+    // vessel_dwt
+    expect(rowA.vessel_dwt).toBe(56000);
+    expect(rowB.vessel_dwt).toBe(rowA.vessel_dwt);
+
+    // vessel_name / cargo_ref
+    expect(rowA.vessel_name).toBe('MV PARITY');
+    expect(rowB.vessel_name).toBe(rowA.vessel_name);
+
+    // economics — both paths use computeStoredMatchEconomics so values should match
+    expect(rowA.tce_usd_per_day).not.toBeNull();
+    expect(rowB.tce_usd_per_day).toBe(rowA.tce_usd_per_day);
+    expect(rowB.freight_rate_usd_per_mt).toBe(rowA.freight_rate_usd_per_mt);
+    expect(rowB.freight_rate_source).toBe(rowA.freight_rate_source);
+    expect(rowB.distance_nm).toBe(rowA.distance_nm);
+    expect(rowB.ballast_distance_nm).toBe(rowA.ballast_distance_nm);
+
+    // consumption_estimated
+    expect(rowB.consumption_estimated).toBe(rowA.consumption_estimated);
+
+    // worksheet_json — both present
+    expect(rowA.worksheet_json).not.toBeNull();
+    expect(rowB.worksheet_json).not.toBeNull();
+
+    // reason_structured — both paths write scoreBreakdown (null when absent)
+    expect(rowA.reason_structured).toBeNull();
+    expect(rowB.reason_structured).toBeNull();
+  });
+});
