@@ -99,6 +101,37 @@ export async function computeAndPersistMatches(
     const freight_rate_source = eco.freight_rate_source;
     const consumption_estimated = eco.consumption_estimated ? 1 : null;

+    // Build worksheet from match readiness/filter data (mirrors persist-session-matches.ts).
