+/**
+ * Write-path parity — B.2
+ *
+ * Verifies that the background precompute path (computeAndPersistMatches) and the
+ * seed path (buildMatchInsertSql / real-matches.ts) both populate the same 21
+ * key columns.
+ *
+ * The 21 columns compared (excluding admin fields id/status/user_id/created_at/updated_at
+ * and the path-exclusive fields vessel_name/cargo_ref/consumption_estimated/ballast_distance_nm):
+ *   cargo_id, vessel_id, cargo_item_index, vessel_item_index,
+ *   score, reason, cargo_type, load_port, discharge_port,
+ *   laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day*, distance_nm*, freight_rate_usd_per_mt*, freight_rate_source*,
+ *   fit_percent, fit_breakdown, worksheet_json, breakeven_tce_usd_per_day, reason_structured
+ *
+ * (* economics may be null when port-distance lookup misses in test environment)
+ *
+ * analyzePairs is mocked so this test is deterministic and LLM-free.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { buildMatchInsertSql, tableHasItemIndexCols } from '@/scripts/demo-seed/real-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_EMAIL_ID = 'parity-cargo-1';
+const VESSEL_EMAIL_ID = 'parity-vessel-1';
+const CARGO_ITEM_INDEX = 2;
+const VESSEL_ITEM_INDEX = 3;
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  [
+    migration032, migration033, migration034, migration035, migration036,
+    migration041, migration042, migration044, migration045, migration046,
+    migration047, migration050,
+  ].forEach((m) => m.up(db));
+  return db;
+}
+
+function makeCargo(): ParsedCargo {
+  return {
+    emailId: CARGO_EMAIL_ID,
+    itemIndex: CARGO_ITEM_INDEX,
+    originPort: { value: 'Hamburg', confidence: 'confirmed' },
+    originCountry: null,
+    destinationPort: { value: 'Rotterdam', confidence: 'confirmed' },
+    destinationCountry: null,
+    cargoDescription: { value: 'Wheat in bulk', confidence: 'confirmed' },
+    weightMt: { value: 15000, confidence: 'confirmed' },
+    weightMtMin: null,
+    weightMtMax: null,
+    volumeCbm: null,
+    dimensions: null,
+    cargoType: 'GRAIN' as const,
+    containerType: null,
+    quantity: null,
+    incoterms: null,
+    preferredDates: null,
+    laycan: '1-15 Jul 2026',
+    loadingRate: null,
+    dischargeRate: null,
+    commissionPercent: null,
+    commissionTerms: null,
+    specialRequirements: null,
+    stowageFactor: null,
+    missingInfo: [],
+  };
+}
+
+function makeVessel(): ParsedVessel {
+  return {
+    emailId: VESSEL_EMAIL_ID,
+    itemIndex: VESSEL_ITEM_INDEX,
+    vesselName: { value: 'MV PARITY TEST', confidence: 'confirmed' },
+    imo: null,
+    flag: null,
+    built: 2010,
+    classSociety: null,
+    pandi: null,
+    dwtSummer: { value: 28000, confidence: 'confirmed' },
+    dwcc: { value: 26000, confidence: 'confirmed' },
+    draftMax: { value: 9.5, confidence: 'confirmed' },
+    loa: null,
+    beam: null,
+    grt: null,
+    nrt: null,
+    holdsCount: null,
+    hatchesCount: null,
+    grainCapacity: 35000,
+    grainCapacityUnit: 'cbm' as const,
+    baleCapacity: null,
+    holdDimensions: null,
+    hatchDimensions: null,
+    tankTopStrength: null,
+    geared: true,
+    craneCapacity: null,
+    hatchType: null,
+    vesselType: 'BULK_CARRIER',
+    openPosition: { value: 'Rotterdam', confidence: 'confirmed' },
+    openDate: { value: '2026-06-20', confidence: 'confirmed' },
+    direction: null,
+    restrictions: [],
+    lastCargoes: null,
+    speedLaden: '12 kts',
+    speedBallast: null,
+    consumption: '22 mt/day',
+    deckCapacity: null,
+    specialFeatures: [],
+  };
+}
+
+const MOCK_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'timing', label: 'Timing', weight: 15, score: 12, rationale: 'opens before laycan' },
+    { factor: 'utilisation', label: 'Utilisation', weight: 19, score: 15, rationale: '~68% DWT' },
+  ],
+  totalWeight: 100,
+  fitPercent: 67,
+  partCargo: false,
+  vesselClass: 'handymax',
+  sanctionsPenalty: 0,
+  chartererPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 80,
+    gapDays: 10,
+    verdict: 'idle',
+    utilisation: 0.68,
+    vesselDwt: 28000,
+    cargoWtMax: 15000,
+  },
+};
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity — B.2 (21 columns)', () => {
+  it('compute path (computeAndPersistMatches) writes fit_breakdown, worksheet_json, breakeven, item-indices', async () => {
+    const db = freshDb();
+
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [
+        {
+          cargoEmailId: CARGO_EMAIL_ID,
+          cargoItemIndex: CARGO_ITEM_INDEX,
+          vesselEmailId: VESSEL_EMAIL_ID,
+          vesselItemIndex: VESSEL_ITEM_INDEX,
+          score: 78,
+          matchLevel: 'good' as const,
+          matchReasons: ['Good timing'],
+          issues: [],
+          fitPercent: MOCK_FIT_BREAKDOWN.fitPercent,
+          fitBreakdown: MOCK_FIT_BREAKDOWN,
+          readiness: {
+            openDate: '2026-06-20',
+            laycanStart: '2026-07-01',
+            laycanEnd: '2026-07-15',
+            distanceNm: 80,
+            speedKn: 12,
+            sailingDays: 0.3,
+            arrivalDate: '2026-06-20',
+            gapDays: 10,
+            verdict: 'idle' as const,
+            explanation: 'idle — 10 days gap',
+          },
+          hardFilters: {
+            draft: { pass: true },
+            crane: { pass: true },
+            volume: { pass: true },
+            cargoVessel: { pass: true },
+            destDraft: { pass: true },
+            destCrane: { pass: true },
+            cargoWeight: { pass: true },
+          },
+          sanctions: { risk: 'NONE' as const, blocking: false },
+        },
+      ],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+
+    await computeAndPersistMatches([makeCargo()], [makeVessel()], 'session-parity', db);
+
+    const [row] = listMatches(db, { user_id: 'session-parity', sortBy: 'score', sortDir: 'desc' });
+    expect(row).toBeDefined();
+
+    // Item indices (new in B.2)
+    expect(row.cargo_item_index).toBe(CARGO_ITEM_INDEX);
+    expect(row.vessel_item_index).toBe(VESSEL_ITEM_INDEX);
+
+    // Fit columns (new in B.2)
+    expect(row.fit_percent).toBe(MOCK_FIT_BREAKDOWN.fitPercent);
+    expect(row.fit_breakdown).not.toBeNull();
+    const parsedFb = JSON.parse(row.fit_breakdown!);
+    expect(parsedFb.fitPercent).toBe(MOCK_FIT_BREAKDOWN.fitPercent);
+    expect(Array.isArray(parsedFb.components)).toBe(true);
+
+    // Worksheet JSON (new in B.2)
+    expect(row.worksheet_json).not.toBeNull();
+    const ws = JSON.parse(row.worksheet_json!);
+    expect(ws).toHaveProperty('readiness');
+    expect(ws).toHaveProperty('vessel');
+    expect(ws).toHaveProperty('cargo');
+    expect(ws).toHaveProperty('hardFilters');
+    expect(ws.readiness.gapDays).toBe(10);
+
+    // Breakeven (new in B.2)
+    expect(row.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(typeof row.breakeven_tce_usd_per_day).toBe('number');
+
+    // Core columns (unchanged)
+    expect(row.cargo_id).toBe(CARGO_EMAIL_ID);
+    expect(row.vessel_id).toBe(VESSEL_EMAIL_ID);
+    expect(row.cargo_type).toBe('GRAIN');
+    expect(row.load_port).toBe('Hamburg');
+    expect(row.discharge_port).toBe('Rotterdam');
+    expect(row.laycan_start).not.toBeNull();
+    expect(row.laycan_end).not.toBeNull();
+    expect(row.vessel_dwt).toBe(28000);
+  });
+
