+
+    const sql = buildMatchInsertSql(hasIdx);
+    const nowMs = Date.now();
+    const laycanStart = new Date('2026-07-01').getTime();
+    const laycanEnd = new Date('2026-07-15').getTime();
+    const fitBreakdownJson = JSON.stringify(MOCK_FIT_BREAKDOWN);
+    const worksheetJson = JSON.stringify({ readiness: { gapDays: 10 }, vessel: {}, cargo: {}, hardFilters: {} });
+
+    db.prepare(sql).run(
+      CARGO_EMAIL_ID, VESSEL_EMAIL_ID,
+      CARGO_ITEM_INDEX, VESSEL_ITEM_INDEX,
+      78, 'Good timing', null, nowMs, nowMs,
+      'GRAIN', 'Hamburg', 'Rotterdam', laycanStart, laycanEnd, 28000,
+      5000, 80, 12.5, 'estimated',
+      MOCK_FIT_BREAKDOWN.fitPercent, fitBreakdownJson, worksheetJson,
+      null, // reason_structured = null (B.1)
+    );
+
+    const [row] = listMatches(db, { sortBy: 'score', sortDir: 'desc' });
+    expect(row).toBeDefined();
+
+    // Same 21 columns non-null / correct in seed path
+    expect(row.cargo_id).toBe(CARGO_EMAIL_ID);
+    expect(row.vessel_id).toBe(VESSEL_EMAIL_ID);
+    expect(row.cargo_item_index).toBe(CARGO_ITEM_INDEX);
+    expect(row.vessel_item_index).toBe(VESSEL_ITEM_INDEX);
+    expect(row.cargo_type).toBe('GRAIN');
+    expect(row.load_port).toBe('Hamburg');
+    expect(row.discharge_port).toBe('Rotterdam');
+    expect(row.laycan_start).toBe(laycanStart);
+    expect(row.laycan_end).toBe(laycanEnd);
+    expect(row.vessel_dwt).toBe(28000);
+    expect(row.tce_usd_per_day).toBe(5000);
+    expect(row.distance_nm).toBe(80);
+    expect(row.freight_rate_usd_per_mt).toBe(12.5);
+    expect(row.freight_rate_source).toBe('estimated');
+    expect(row.fit_percent).toBe(MOCK_FIT_BREAKDOWN.fitPercent);
+    expect(row.fit_breakdown).toBe(fitBreakdownJson);
+    expect(row.worksheet_json).toBe(worksheetJson);
+    expect(row.reason_structured).toBeNull();
+  });
+
+  it('both paths write non-null fit_breakdown and worksheet_json — column coverage matches', async () => {
+    const db = freshDb();
+
+    // Compute path
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [
+        {
+          cargoEmailId: CARGO_EMAIL_ID,
+          cargoItemIndex: 0,
+          vesselEmailId: VESSEL_EMAIL_ID,
+          vesselItemIndex: 0,
+          score: 70,
+          matchLevel: 'good' as const,
+          matchReasons: ['parity'],
+          issues: [],
+          fitPercent: 60,
+          fitBreakdown: MOCK_FIT_BREAKDOWN,
+          readiness: {
+            openDate: '2026-06-20', laycanStart: '2026-07-01', laycanEnd: '2026-07-15',
+            distanceNm: 80, speedKn: 12, sailingDays: 0.3, arrivalDate: '2026-06-20',
+            gapDays: 10, verdict: 'idle' as const, explanation: 'idle',
+          },
+          hardFilters: {
+            draft: { pass: true }, crane: { pass: true }, volume: { pass: true },
+            cargoVessel: { pass: true }, destDraft: { pass: true },
