+      70, 'parity', '__demo_seed__', nowMs, nowMs,
+      'GRAIN', 'Hamburg', 'Rotterdam',
+      new Date('2026-07-01').getTime(), new Date('2026-07-15').getTime(), 28000,
+      5000, 80, 12.5, 'estimated',
